      SUBROUTINE MRTR2CC     MULTIPLIES RT AND RC2 AND ADDS RESULT TO R2VCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R2VS.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'US.CIN'CC---------------------------------------------------------      N = NV2      IF (R2P) GO TO 50      DO 10 JK = 1, 36   10 R2VSL(JK,N) = RTL(JK)      IF (NORD2 .GE. 2) THEN        DO 20 IJK = 1, 105   20   T2VL(IJK,N) = TTL(IJK)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 IJKL = 1, 280   30   U2VL(IJKL,N) = UTL(IJKL)      ENDIF      R2VP(N) = .TRUE.      GO TO 200C   50 IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RT,RC2)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CAB2(RS,TS,RT,TT,RC2,TC2)      ELSE IF (NORD2 .GE. 3) THEN        CALL CAB3(RS,TS,US,RT,TT,UT,RC2,TC2,UC2)      ENDIFC      IF (R2VP(N)) GO TO 100      DO 60 JK = 1, 36   60 R2VSL(JK,N) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 70 IJK = 1, 105   70   T2VL(IJK,N) = TSL(IJK)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 80 IJKL = 1, 280   80   U2VL(IJKL,N) = USL(IJKL)      ENDIF      R2VP(N) = .TRUE.      GO TO 200C  100 DO 110 JK = 1, 36  110 R2VSL(JK,N) = R2VSL(JK,N) + RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 120 IJK = 1, 105  120   T2VL(IJK,N) = T2VL(IJK,N) + TSL(IJK)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 130 IJKL = 1, 280  130   U2VL(IJKL,N) = U2VL(IJKL,N) + USL(IJKL)      ENDIFC  200 RETURN      END